import { ERRORS, integer } from '../';

const validIntegers = [
  null,
  0,
  4,
  -1,
  '',
  '1',
  '-1',
  '123',
  '64',
  '0',
  '-0',
  '-123456789',
];

const invalidIntegers = [
  false,
  [],
  '01.01',
  '0.',
  -1.1,
  25.32,
  -25.32,
  '1.1',
  '-1.1',
  '1.',
  '123.123',
  'a',
  '-a',
  'a.a',
  '-a.a',
  '1a',
  'a1',
  'abc',
  '2tr5.i32',
  '-1a',
  '--1',
  '1..1',
  '..',
  'a-',
  'a.-',
  '--5-3-.-2-7-',
  '25.32',
  '-25.32',
  '.123456789',
  '-.123456789',
  '-123456789.12345789',
];

describe('integer validator', () => {
  validIntegers.forEach((value) => {
    it(`'${value}' passes`, () => {
      expect(
        integer({
          errors: [],
          value,
        }),
      ).toEqual([]);
    });
  });

  invalidIntegers.forEach((value) => {
    it(`'${value}' fails`, () => {
      expect(
        integer({
          errors: [],
          value,
        }),
      ).toEqual([ERRORS.invalidInteger]);
    });
  });
});
